import fs from "fs";
import path from "path";
import { ImageResponse } from "next/og";

// Text diagrams (box drawing) are generated by scripts/og-diagrams.py and
// rendered here. DejaVu Sans Mono is used because it has the box-drawing glyphs
// and its advance width is a fixed 0.602em, so columns line up.
const FONT_DIR = path.join(process.cwd(), "app", "fonts");
const ADVANCE = 0.602; // glyph width in em
const LINE = 1.16; // em; just under the glyph height so │ overlaps and joins between rows

const COLORS = {
  background: "#FBFAF7",
  foreground: "#23272F",
  brand: "#087EA4",
};

let fonts: { regular: Buffer; bold: Buffer } | null = null;
function loadFonts() {
  fonts ??= {
    regular: fs.readFileSync(path.join(FONT_DIR, "DejaVuSansMono.ttf")),
    bold: fs.readFileSync(path.join(FONT_DIR, "DejaVuSansMono-Bold.ttf")),
  };
  return fonts;
}

export function readDiagram(file: string): string[] | null {
  try {
    return fs.readFileSync(file, "utf8").replace(/\n+$/, "").split("\n");
  } catch {
    return null;
  }
}

interface RenderOptions {
  width: number;
  height: number;
  /** Space kept free on every side, in px. */
  margin?: number;
  bold?: boolean;
  /** Rows from this index on are drawn in the brand colour. */
  accentFrom?: number;
  background?: string;
  foreground?: string;
  /** Shift the text down by this many em, e.g. to centre capitals optically. */
  offsetY?: number;
}

export function renderDiagram(
  lines: string[],
  {
    width,
    height,
    margin = 0,
    bold = false,
    accentFrom = Infinity,
    background = COLORS.background,
    foreground = COLORS.foreground,
    offsetY = 0,
  }: RenderOptions,
) {
  const cols = Math.max(...lines.map((line) => line.length));
  const fontSize = Math.floor(
    Math.min(
      (width - margin * 2) / (cols * ADVANCE),
      (height - margin * 2) / (lines.length * LINE),
    ),
  );
  const { regular, bold: boldFont } = loadFonts();

  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            position: "relative",
            top: Math.round(offsetY * fontSize),
          }}
        >
          {lines.map((line, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                height: fontSize * LINE,
                width: cols * ADVANCE * fontSize,
                fontSize,
                lineHeight: LINE,
                whiteSpace: "pre",
                fontFamily: "DejaVu Sans Mono",
                fontWeight: bold ? 700 : 400,
                color: i >= accentFrom ? COLORS.brand : foreground,
              }}
            >
              {line || " "}
            </div>
          ))}
        </div>
      </div>
    ),
    {
      width,
      height,
      fonts: [
        { name: "DejaVu Sans Mono", data: regular, weight: 400, style: "normal" },
        { name: "DejaVu Sans Mono", data: boldFont, weight: 700, style: "normal" },
      ],
    },
  );
}

export const OG_SIZE = { width: 1200, height: 630 };

/** Social preview: the title box in the text colour, arrow + footer box in brand. */
export function renderOgDiagram(lines: string[]) {
  const footerStart = lines.findIndex((line) => line.startsWith("└"));
  return renderDiagram(lines, {
    ...OG_SIZE,
    margin: 60,
    bold: true,
    accentFrom: footerStart === -1 ? Infinity : footerStart + 1,
  });
}
